class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

function parseAge(input) {
  let value;
  if (typeof input === 'number') {
    value = input;
  } else if (typeof input === 'string') {
    if (!/^\s*\d+\s*$/.test(input)) throw new ValidationError('Age must be a whole number');
    value = Number(input);
  } else {
    throw new TypeError('Age must be a string or number');
  }
  if (!Number.isInteger(value)) throw new ValidationError('Age must be a whole number');
  if (value < 0 || value > 150) throw new ValidationError('Age must be between 0 and 150');
  return value;
}

