const KNOWN = ['paid', 'pending', 'failed'];

function badgeView(order) {
  const known = KNOWN.includes(order.status);
  const label = known ? order.status[0].toUpperCase() + order.status.slice(1) : 'Unknown';
  const noun = order.itemCount === 1 ? 'item' : 'items';
  const classes = ['badge', known ? `badge--${order.status}` : 'badge--unknown'];
  if (order.itemCount === 0) classes.push('badge--empty');
  return {
    text: `${label} · ${order.itemCount} ${noun}`,
    classes,
    attributes: { 'aria-live': 'polite', 'data-updated': order.updatedAt },
  };
}

