function buildList(items) {
  return {
    tag: 'ul',
    classes: ['items'],
    children: items.map((item) => {
      const classes = ['item'];
      if (item.done) classes.push('item--done');
      return { tag: 'li', classes, dataset: { id: String(item.id) }, text: item.name };
    }),
  };
}

