function resolveAction(target) {
  let node = target;
  while (node && !('action' in node.dataset)) node = node.parent;
  if (!node) return null;
  const action = node.dataset.action;
  let cursor = node;
  while (cursor && !('id' in cursor.dataset)) cursor = cursor.parent;
  return { action, id: cursor ? cursor.dataset.id : null };
}

