function validateSignup(values) {
  const errors = {};
  const { email = '', password = '', confirm = '', age = '', terms = false } = values;
  if (!/^[^@]+@[^@]+$/.test(email)) errors.email = 'Enter a valid email';
  if (password.length < 8 || !/\d/.test(password)) errors.password = 'Password needs 8+ characters and a digit';
  if (confirm !== password) errors.confirm = 'Passwords do not match';
  const ageNumber = /^\d+$/.test(String(age).trim()) ? Number(age) : NaN;
  if (!(ageNumber >= 13 && ageNumber <= 120)) errors.age = 'Enter an age between 13 and 120';
  if (terms !== true) errors.terms = 'Accept the terms to continue';
  return errors;
}

function schedule(items) {
  const fired = [];
  const ids = [];
  let settled = false;
  let resolveDone;
  const promise = new Promise((resolve) => {
    resolveDone = resolve;
  });
  const finish = () => {
    if (settled) return;
    settled = true;
    resolveDone(fired);
  };
  if (items.length === 0) finish();
  for (const [name, delay] of items) {
    ids.push(setTimeout(() => {
      fired.push(name);
      if (fired.length === items.length) finish();
    }, delay));
  }
  return {
    promise,
    cancel() {
      ids.forEach(clearTimeout);
      finish();
    },
  };
}

