async function getJSON(url, options = {}, fetchImpl = globalThis.fetch) {
  const response = await fetchImpl(url, options);
  if (!response.ok) {
    throw new Error(`Request failed: ${response.status}`, { cause: response });
  }
  return response.json();
}

async function postJSON(url, body, fetchImpl = globalThis.fetch) {
  return getJSON(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }, fetchImpl);
}

function createRegistry() {
  const factories = new Map();
  const cache = new Map();
  function require(name) {
    if (cache.has(name)) return cache.get(name);
    const factory = factories.get(name);
    if (!factory) throw new Error(`Module not found: ${name}`);
    const exports = factory(require);
    cache.set(name, exports);
    return exports;
  }
  function define(name, factory) {
    if (!cache.has(name)) factories.set(name, factory);
  }
  return { define, require };
}

