function createTodoStore(storage, key = 'todos') {
  let state = [];
  let seq = 0;
  const makeId = () => (globalThis.crypto?.randomUUID ? crypto.randomUUID() : `t${Date.now()}-${++seq}`);

  try {
    const raw = storage.getItem(key);
    const parsed = raw ? JSON.parse(raw) : [];
    if (Array.isArray(parsed)) state = parsed;
  } catch {
    state = [];
  }

  function setState(next) {
    state = next;
    try {
      storage.setItem(key, JSON.stringify(state));
    } catch {
      // storage unavailable; keep working in memory
    }
  }

  return {
    getState: () => state,
    add(text) {
      const todo = { id: makeId(), text, done: false };
      setState([...state, todo]);
      return todo;
    },
    toggle(id) {
      setState(state.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
    },
    remove(id) {
      setState(state.filter((t) => t.id !== id));
    },
    clearDone() {
      setState(state.filter((t) => !t.done));
    },
  };
}
